// Generated from src/registry/sources/control-ui/recipes/emoji-picker.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const emojiPickerKnobs = [
  "--cui-emoji-picker-cell-size",
  "--cui-emoji-picker-height",
  "--cui-emoji-picker-cell-radius",
  "--cui-emoji-picker-glyph-size",
  "--cui-emoji-picker-active-background",
  "--cui-emoji-picker-header-background",
  "--cui-emoji-picker-header-foreground",
] as const;
export type EmojiPickerKnobStyle = Partial<Record<(typeof emojiPickerKnobs)[number], string>>;

@layer components {
  :where([data-control-family="emoji-picker"][data-slot="root"]) {
    --cui-emoji-picker-cell-size: calc(var(--spacing) * 10);
    --cui-emoji-picker-cell-radius: var(--radius-control);
    --cui-emoji-picker-glyph-size: 1.25rem;
    --cui-emoji-picker-active-background: var(--accent);
    --cui-emoji-picker-header-background: var(--popover);
    --cui-emoji-picker-header-foreground: var(--muted-foreground);
    --cui-emoji-picker-height: 22rem;
    --_emoji-picker-recent-block-size: 0px;
  }
  :where([data-control-family="emoji-picker"][data-slot="root"]:not([data-variant="reactions"])) {
    inline-size: calc(var(--_emoji-picker-columns) * var(--cui-emoji-picker-cell-size) + var(--spacing) * 4);
    max-inline-size: 100%;
    block-size: var(--cui-emoji-picker-height);
    color: var(--foreground);
    font-family: var(--font-sans);
  }

  :where([data-control-family="emoji-picker"][data-slot="categories"]) {
    display: flex;
    justify-content: space-between;
    flex-shrink: 0;
    overflow-x: auto;
    padding-inline: calc(var(--spacing) * 1.5);
  }
  :where([data-control-family="emoji-picker"][data-slot="category"]) {
    display: grid;
    place-items: center;
    flex: 0 0 calc(var(--spacing) * 9);
    block-size: calc(var(--spacing) * 9);
    border-radius: var(--cui-emoji-picker-cell-radius);
    color: var(--muted-foreground);
    cursor: pointer;
    transition:
      color var(--duration-fast) var(--ease-standard),
      background-color var(--duration-fast) var(--ease-standard);
  }
  :where([data-control-family="emoji-picker"][data-slot="category"]:hover) {
    color: var(--foreground);
    background: var(--cui-emoji-picker-active-background);
  }
  :where([data-control-family="emoji-picker"][data-slot="category"] svg) {
    inline-size: calc(var(--spacing) * 4);
    block-size: calc(var(--spacing) * 4);
  }
  :where([data-control-family="emoji-picker"][data-slot="recent-label"]) {
    position: sticky;
    inset-block-start: 0;
    z-index: 1;
    box-sizing: border-box;
    block-size: var(--frimousse-category-header-height, auto);
  }
  :where([data-control-family="emoji-picker"]:is([data-slot="recent-grid"], [data-variant="reactions"])) {
    display: flex;
  }
  :where([data-control-family="emoji-picker"][data-slot="recent-grid"]) {
    block-size: var(--frimousse-row-height, auto);
    padding-inline: calc(var(--spacing) * 1.5);
  }
  :where([data-control-family="emoji-picker"][data-slot="root"]:has([data-slot="recent"])) {
    --_emoji-picker-recent-block-size: calc(var(--frimousse-category-header-height) + var(--frimousse-row-height));
  }
  :where([data-control-family="emoji-picker"][data-slot="root"]:has(input:not(:placeholder-shown))) {
    --_emoji-picker-recent-block-size: 0px;
  }
  :where(
    [data-control-family="emoji-picker"][data-slot="root"]:has(input:not(:placeholder-shown))
      :is([data-slot="categories"], [data-slot="recent"])
  ) {
    display: none;
  }
  :where([data-control-family="emoji-picker"][data-slot="error"]) {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: calc(var(--spacing) * 2);
    block-size: 100%;
    color: var(--muted-foreground);
    font-size: var(--text-label);
  }
  :where([data-control-family="emoji-picker"][data-slot="error"] button) {
    color: var(--foreground);
    text-decoration: underline;
    min-block-size: 44px;
    cursor: pointer;
  }
  :where([data-control-family="emoji-picker"][data-slot="search"]) {
    position: relative;
    margin: calc(var(--spacing) * 2);
    margin-block-end: calc(var(--spacing) * 1);
  }

  :where([data-control-family="emoji-picker"][data-slot="search-icon"]) {
    position: absolute;
    inset-inline-start: calc(var(--spacing) * 2.5);
    inline-size: calc(var(--spacing) * 4);
    block-size: calc(var(--spacing) * 4);
    color: var(--muted-foreground);
    pointer-events: none;
  }

  :where([data-control-family="emoji-picker"][data-slot="search-input"]) {
    block-size: var(--control-h-sm);
    padding-inline: calc(var(--spacing) * 8) calc(var(--spacing) * 2.5);
    border: var(--control-rim-width) solid var(--control-rim);
    border-radius: var(--radius-control);
    background: var(--control-fill);
    box-shadow: var(--shadow-inset);
    color: var(--foreground);
    font-size: var(--text-label);
    --focus-ring-offset: calc(var(--focus-ring-width) * -1);
  }

  :where([data-control-family="emoji-picker"][data-slot="search-input"])::placeholder {
    color: var(--muted-foreground);
  }

  :where([data-control-family="emoji-picker"][data-slot="loading"]),
  :where([data-control-family="emoji-picker"][data-slot="empty"]) {
    color: var(--muted-foreground);
    font-size: var(--text-label);
  }

  :where([data-control-family="emoji-picker"][data-slot="list"]) {
    padding-block-end: calc(var(--spacing) * 1);
  }

  :where([data-control-family="emoji-picker"]:is([data-slot="category-header"], [data-slot="recent-label"])) {
    padding: calc(var(--spacing) * 1.5) calc(var(--spacing) * 2.5) calc(var(--spacing) * 1);
    background: var(--cui-emoji-picker-header-background);
    color: var(--cui-emoji-picker-header-foreground);
    font-size: var(--text-caption);
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="emoji-picker"][data-slot="row"]) {
    padding-inline: calc(var(--spacing) * 1.5);
    scroll-margin-block: var(--spacing) calc(var(--spacing) + var(--_emoji-picker-recent-block-size));
  }

  :where([data-control-family="emoji-picker"][data-slot="emoji"]) {
    inline-size: var(--cui-emoji-picker-cell-size);
    block-size: var(--cui-emoji-picker-cell-size);
    border-radius: var(--cui-emoji-picker-cell-radius);
    background: transparent;
    font-size: var(--cui-emoji-picker-glyph-size);
    line-height: 1;
    cursor: default;
    transition: background-color var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="emoji-picker"][data-slot="emoji"][data-active]),
  :where([data-control-family="emoji-picker"][data-variant="reactions"] > [data-slot="emoji"]:hover) {
    background: var(--cui-emoji-picker-active-background);
  }

  :where([data-control-family="emoji-picker"][data-slot="footer"]) {
    gap: calc(var(--spacing) * 2);
    min-block-size: calc(var(--spacing) * 11);
    padding-inline: calc(var(--spacing) * 2.5);
    border-block-start: 1px solid var(--border);
    color: var(--muted-foreground);
    font-size: var(--text-label);
  }

  :where([data-control-family="emoji-picker"][data-slot="footer-emoji"]) {
    font-size: var(--cui-emoji-picker-glyph-size);
    line-height: 1;
  }

  :where([data-control-family="emoji-picker"][data-slot="footer-label"]) {
    color: var(--foreground);
  }

  @media (pointer: coarse) {
    :where([data-control-family="emoji-picker"][data-slot="root"]) {
      --cui-emoji-picker-cell-size: 44px;
    }
    :where([data-control-family="emoji-picker"][data-slot="category"]) {
      flex-basis: 44px;
      block-size: 44px;
    }
    :where([data-control-family="emoji-picker"][data-slot="search-input"]) {
      font-size: 16px;
    }
  }
}

